import sys

def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    a = [int(x) for x in data[2:2 + n]]
    b = [int(x) for x in data[2 + n:2 + n + m]]
    pre = set()
    for x in a:
        while x and x not in pre:
            pre.add(x)
            x //= 10
    best = 0
    for y in b:
        while y and y not in pre:
            y //= 10
        if y:
            best = max(best, len(str(y)))
    print(best)

